/**
 * QueryConditionElement
 *
 * Require a condition to match within one element of a registered object array.
 */
export type QueryConditionElement = {
    /**
     * Condition
     */
    condition: ({
        type: 'predicate';
    } & QueryConditionPredicate) | ({
        type: 'all' | 'any' | 'nor';
    } & QueryConditionGroup) | ({
        type: 'not';
    } & QueryConditionNot) | ({
        type: 'elem_match';
    } & QueryConditionElement);
    /**
     * Field
     */
    field: string;
    /**
     * Type
     */
    type: 'elem_match';
};

/**
 * QueryConditionGroup
 *
 * Join a nonempty set of conditions using AND, OR or NOR.
 */
export type QueryConditionGroup = {
    /**
     * Children
     */
    children: Array<QueryConditionPredicate | QueryConditionGroup | QueryConditionNot | QueryConditionElement>;
    /**
     * Type
     */
    type: 'all' | 'any' | 'nor';
};

/**
 * QueryConditionNot
 *
 * Invert one complete condition, including its missing-field behavior.
 */
export type QueryConditionNot = {
    /**
     * Child
     */
    child: ({
        type: 'predicate';
    } & QueryConditionPredicate) | ({
        type: 'all' | 'any' | 'nor';
    } & QueryConditionGroup) | ({
        type: 'not';
    } & QueryConditionNot) | ({
        type: 'elem_match';
    } & QueryConditionElement);
    /**
     * Type
     */
    type: 'not';
};

/**
 * QueryConditionPredicate
 *
 * Compare a registered finding field with a literal or registered sample-filter reference.
 */
export type QueryConditionPredicate = {
    /**
     * Field
     */
    field: string;
    /**
     * Operator
     */
    operator: string;
    /**
     * Type
     */
    type: 'predicate';
    /**
     * Value
     */
    value: unknown;
};

/**
 * QueryConditionTest
 *
 * Evaluate a condition against caller-supplied examples without database retrieval.
 */
export type QueryConditionTest = {
    /**
     * Analysis
     */
    analysis: 'snv' | 'cnv' | 'translocation' | 'fusion';
    /**
     * Condition
     */
    condition: ({
        type: 'predicate';
    } & QueryConditionPredicate) | ({
        type: 'all' | 'any' | 'nor';
    } & QueryConditionGroup) | ({
        type: 'not';
    } & QueryConditionNot) | ({
        type: 'elem_match';
    } & QueryConditionElement);
    /**
     * Documents
     */
    documents: Array<{
        [key: string]: unknown;
    }>;
};

/**
 * QueryConditionTestResult
 *
 * Return one match result per input example and the compiled condition predicate.
 */
export type QueryConditionTestResult = {
    /**
     * Matches
     */
    matches: Array<boolean>;
    /**
     * Predicate
     */
    predicate: {
        [key: string]: unknown;
    };
};

